"""Tests for metrics.counters (hits)."""

from metrics.counters import Metrics  # noqa: F401

import unittest


class TestMetrics(unittest.TestCase):
    def setUp(self):
        Metrics.hits = 0

    def test_record_hit_increments(self):
        Metrics.record_hit()
        self.assertEqual(Metrics.hits, 1)


if __name__ == "__main__":
    unittest.main()

